mapper.update:
UPDATE car
owner_id = #{ownerId}, asset_id = #{assetId}, visitor_id = #{visitorId}, car_number = #{carNumber}, car_type = #{carType}, car_status = #{carStatus},
WHERE id = #{id}

mapper.select:
SELECT c.*, u.user_name AS owner_name, u.uid AS owner_uid, a.asset_name, ct.car_type_name FROM car c LEFT JOIN user u ON c.owner_id = u.id LEFT JOIN asset a ON c.asset_id = a.id LEFT JOIN car_type ct ON c.car_type = ct.car_type_id
AND c.owner_id = #{ownerId}
AND u.uid LIKE CONCAT('%', #{ownerUid}, '%')
AND c.car_number LIKE CONCAT('%', #{carNumber}, '%')
AND c.car_type = #{carType}
AND c.car_status = #{carStatus}
ORDER BY c.id ASC
